var InstantClick = function(document, location) {
  var _url = location.href,
      _referrer = false,
      _title = false,
      _isFadingOut = false,
      _body = false,
      _lastTouchTimestamp,
      _cache = {},
      _xhr,
      _urlToFetch = false,
      _isFetching = false,
      _isDisplaying = false,
      _isWaitingForDisplay = false,
      _trackedAssets = [],
      _hasDataNoInstant,
      _isMouseDownDelay,
      _delayBeforePreload,
      _events = {
        fetch: [],
        receive: [],
        wait: [],
        change: []
      };

  /* --- Helpers --- */

  function stripHash(url) {
    var index = url.indexOf('#');
    if (index < 0) return url;
    return url.substr(0, index);
  }

  function getClosestTarget(el) {
    while (el && el.nodeName !== 'A') {
      el = el.parentNode;
    }
    return el;
  }

  function isEligible(a) {
    var domain = location.protocol + '//' + location.host;
    if (a.target || 
        a.hasAttribute('download') || 
        a.href.indexOf(domain + '/') !== 0 || 
        (a.href.indexOf('#') > -1 && stripHash(a.href) === _url)) {
      return false;
    }
    
    // Check data-no-instant attributes
    var el = a;
    if (_hasDataNoInstant) {
      while (el && el.hasAttribute) {
        if (el.hasAttribute('data-no-instant')) return false;
        if (el.hasAttribute('data-instant')) break;
        el = el.parentNode;
      }
    } else {
      while (el && el.hasAttribute) {
        if (el.hasAttribute('data-instant')) break;
        if (el.hasAttribute('data-no-instant')) return false;
        el = el.parentNode;
      }
    }
    return true;
  }

  function triggerEvent(name, b, c, g) {
    var returnValue = false;
    for (var i = 0; i < _events[name].length; i++) {
      if (name === 'receive') {
        var result = _events[name][i](b, c, g);
        if (result) {
          if ('body' in result) c = result.body;
          if ('title' in result) g = result.title;
          returnValue = result;
        }
      } else {
        _events[name][i](b, c, g);
      }
    }
    return returnValue;
  }

  function display(title, body, url, scrollY) {
    document.documentElement.replaceChild(body, document.body);
    
    if (url) {
      history.pushState(null, null, url);
      var hashIndex = url.indexOf('#');
      var hashElement = hashIndex > -1 && document.getElementById(url.substr(hashIndex + 1));
      var finalScrollY = 0;
      if (hashElement) {
        while (hashElement.offsetParent) {
          finalScrollY += hashElement.offsetTop;
          hashElement = hashElement.offsetParent;
        }
      }
      scrollTo(0, finalScrollY);
      _url = stripHash(url);
    } else {
      scrollTo(0, scrollY);
    }
    
    _isDisplaying = false;
    _isWaitingForDisplay = false;
    bar.done();
    triggerEvent('change', false);
  }

  /* --- Core Logic --- */

  function preload(url) {
    if (_isFetching && (url === _urlToFetch || _isWaitingForDisplay)) return;
    
    _isFetching = true;
    _isWaitingForDisplay = false;
    _urlToFetch = url;
    _body = false;
    
    triggerEvent('fetch');
    _xhr.open('GET', url);
    _xhr.send();
  }

  function onReceive() {
    if (_xhr.readyState < 4 || _xhr.status === 0) return;
    
    if (_xhr.getResponseHeader('Content-Type').match(/\/(x|ht|xht)ml/)) {
      var doc = document.implementation.createHTMLDocument("");
      doc.documentElement.innerHTML = _xhr.responseText.replace(/<noscript[\s\S]+<\/noscript>/gi, "");
      _title = doc.title;
      _body = doc.body;
      
      var urlKey = stripHash(_urlToFetch);
      _cache[urlKey] = { body: _body, title: _title, scrollY: urlKey in _cache ? _cache[urlKey].scrollY : 0 };
    }
    
    if (_isWaitingForDisplay) {
      _isWaitingForDisplay = false;
      display(_title, _body, _urlToFetch);
    }
  }

  /* --- UI / Bar Logic --- */

  var bar = function() {
    var container, barElement, transformProp, progress;

    function init() {
      container = document.createElement('div');
      container.id = 'instantclick';
      barElement = document.createElement('div');
      barElement.id = 'instantclick-bar';
      barElement.className = 'instantclick-bar';
      container.appendChild(barElement);

      var style = document.createElement('style');
      style.innerHTML = "#instantclick{position:fixed;top:0;left:0;width:100%;pointer-events:none;z-index:2147483647;transition:opacity .25s .1s}.instantclick-bar{background:#29d;width:100%;margin-left:-100%;height:2px;transition:all .25s}";
      document.head.appendChild(style);
    }

    return {
      init: init,
      start: function() {
        if (!document.getElementById('instantclick')) document.body.appendChild(container);
        container.style.opacity = "1";
        progress = 10;
        barElement.style.transform = "translate(" + progress + "%)";
      },
      done: function() {
        progress = 100;
        barElement.style.transform = "translate(" + progress + "%)";
        container.style.opacity = "0";
      }
    };
  }();

  /* --- Initialization --- */

  return {
    init: function() {
      if (_url) return; 
      var arg = arguments[0];
      if (arg === true) _hasDataNoInstant = true;
      else if (arg === 'mousedown') _isMouseDownDelay = true;
      else if (typeof arg === 'number') _delayBeforePreload = arg;

      _url = stripHash(location.href);
      _cache[_url] = { body: document.body, title: document.title, scrollY: pageYOffset };
      
      _xhr = new XMLHttpRequest();
      _xhr.addEventListener('readystatechange', onReceive);
      
      bar.init();
      
      document.body.addEventListener('touchstart', function(e) {
        var a = getClosestTarget(e.target);
        if (a && isEligible(a)) preload(a.href);
      }, true);

      document.body.addEventListener('mouseover', function(e) {
        var a = getClosestTarget(e.target);
        if (a && isEligible(a)) preload(a.href);
      }, true);

      document.body.addEventListener('click', function(e) {
        var a = getClosestTarget(e.target);
        if (a && isEligible(a)) {
          e.preventDefault();
          _isWaitingForDisplay = true;
          bar.start();
          if (_body) display(_title, _body, _urlToFetch);
        }
      }, true);
    },
    on: function(type, callback) { _events[type].push(callback); }
  };
}(document, location);
